Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;

const int N = 205;
const int M = N * N;

int read() { int x; scanf("%d", &x); return x; }

int head[2*N], nxt[M], to[M], cap[M], ec;
int mark[2*N];

void add_edge(int u, int v, int uv, int vu) {
    nxt[ec] = head[u]; to[ec] = v; cap[ec] = uv; head[u] = ec++;
    nxt[ec] = head[v]; to[ec] = u; cap[ec] = vu; head[v] = ec++;
}

int dfs(int v, int sink, int flow) {
    if (v == sink) return flow;
    if (mark[v]++) return 0;
    for (int e = head[v]; e != -1; e = nxt[e]) if (cap[e]) {
        int u = to[e];
        int x = dfs(u, sink, min(flow, cap[e]));
        if (x) {
            cap[e] -= x;
            cap[e^1] += x;
            return x;
        }
    }
    return 0;
}

int max_flow(int source, int sink) {
    int res = 0;
    while (true) {
        memset(mark, 0, sizeof mark);
        int add = dfs(source, sink, 2000000000);
        res += add;
        if (!add) break;
    }
    return res;
}

int main() {
    int n = read(), dt = read();
    memset(head, -1, sizeof head);
    int a[N][N] = {{0}}, b[N][N] = {{0}};
    bool red[N][N] = {{false}}, block[N][N] = {{false}};
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; scanf(" %c", &c);
            if (c == 'Y') block[x][y] = true;
            else if (c == 'Z') red[x][y] = true;
            else a[x][y] = c - '0';
        }
    }
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; scanf(" %c", &c);
            if (c != 'Y' && c != 'Z') b[x][y] = c - '0';
        }
    }
    int m = n*n;
    int dis[N*N][N*N];
    for (int i=0; i<m; ++i) for (int j=0; j<m; ++j) dis[i][j] = (i==j?0:1000000000);
    int dx[4] = {0,-1,0,1};
    int dy[4] = {1,0,-1,0};
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            if (block[x][y] || red[x][y]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j]) {
                    dis[x*n+y][i*n+j] = 1;
                }
            }
        }
    }
    for (int k=0; k<m; ++k)
        for (int i=0; i<m; ++i)
            for (int j=0; j<m; ++j)
                if (dis[i][k] + dis[k][j] < dis[i][j])
                    dis[i][j] = dis[i][k] + dis[k][j];
    int dred[N*N];
    for (int i=0; i<m; ++i) dred[i] = 1000000000;
    pii q[N*N];
    int h=0, t=0;
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (red[i][j]) {
                q[t++] = {i,j};
                dred[i*n+j] = 0;
            }
    while (h != t) {
        auto cur = q[h++];
        int x = cur.first, y = cur.second;
        for (int d=0; d<4; ++d) {
            int i = x+dx[d], j = y+dy[d];
            int id = i*n+j;
            if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dred[id] > 1000000000) {
                dred[id] = dred[x*n+y] + 1;
                q[t++] = {i,j};
            }
        }
    }
    int source = N-2, sink = N-1;
    bool seen[N*N];
    for (int cur=0; cur<m; ++cur) {
        int sx = cur/n, sy = cur%n;
        if (block[sx][sy] || red[sx][sy]) continue;
        memset(seen, 0, sizeof seen);
        h = 0; t = 0;
        q[t++] = {sx,sy};
        seen[cur] = true;
        while (h != t) {
            auto p = q[h++];
            int x = p.first, y = p.second;
            int id = x*n+y;
            if (dis[cur][id] <= dt)
                add_edge(cur<<1, (id<<1)|1, 1000, 0);
            if (dis[cur][id] == dred[id]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                int nid = i*n+j;
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dis[cur][nid] <= dred[nid] && dis[cur][nid] <= dt && dis[cur][nid] > dis[cur][id] && !seen[nid]) {
                    seen[nid] = true;
                    q[t++] = {i,j};
                }
            }
        }
    }
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge(source, (i*n+j)<<1, a[i][j], 0);
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge((i*n+j)<<1|1, sink, b[i][j], 0);
    printf("%d\n", max_flow(source, sink));
    return 0;
}
